"""Minimum Speed to Arrive on Time — binary search on speed.

Every leg but the last is rounded up to a whole hour. The upper bound 10^7 comes
from the problem's constraints.

Time: O(n log 10^7)   Space: O(1)
"""
from typing import List


class Solution:
    def minSpeedOnTime(self, dist: List[int], hour: float) -> int:
        if hour <= len(dist) - 1:
            return -1                       # even infinite speed cannot help

        def time_at(speed: int) -> float:
            total = sum((d + speed - 1) // speed for d in dist[:-1])
            return total + dist[-1] / speed

        lo, hi = 1, 10 ** 7
        while lo < hi:
            mid = (lo + hi) // 2
            if time_at(mid) <= hour:
                hi = mid
            else:
                lo = mid + 1
        return lo if time_at(lo) <= hour else -1
